/**
 * Exo DURBIN driver: mirrors PolyBench/C durbin.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"

/* Include the Exo-generated kernel header. */
#include "generated/durbin/durbin.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Optimized Durbin kernel:
# - Uses in-place symmetric updates for y[0..k-1] instead of a
#   temporary z buffer. This:
#     * cuts y[] loads roughly in half,
#     * removes all traffic to/from the temporary z[],
#     * keeps the same arithmetic operations and numerical results.
@proc
def kernel_durbin_base(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE
    tmp_left: DATA_TYPE
    tmp_right: DATA_TYPE

    # Initial conditions (k = 0 step)
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    for k in seq(1, n):
        # Update beta: beta *= (1 - alpha^2)
        beta = (1.0 - alpha * alpha) * beta

        # Compute sum_{i=0}^{k-1} r[k-i-1] * y[i]
        sum = 0.0
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        # Reflection coefficient
        alpha = -(r[k] + sum) / beta

        # In-place symmetric update of y[0..k-1].
        # Each iteration uses the old pair (y[i], y[k-i-1]) and
        # writes both new values back, so every y[t] is read once
        # and written once.
        for i in seq(0, k / 2):
            tmp_left = y[i]
            tmp_right = y[k - i - 1]
            y[i] = tmp_left + alpha * tmp_right
            y[k - i - 1] = tmp_right + alpha * tmp_left

        # If k is odd, there is a center element i = k/2 that is
        # its own symmetric partner and must be updated once more.
        if k % 2 == 1:
            y[k / 2] = (1.0 + alpha) * y[k / 2]

        # Last element is always alpha
        y[k] = alpha


# Scheduling: run Exo's simplifier on the optimized in-place kernel
# and expose the result under the original name `kernel_durbin`.
kernel_durbin_opt = simplify(kernel_durbin_base)
kernel_durbin = rename(kernel_durbin_opt, "kernel_durbin")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 1D views to raw pointers. */
  kernel_durbin(/*ctxt=*/NULL,
                n,
                (DATA_TYPE*)POLYBENCH_ARRAY(r),
                (DATA_TYPE*)POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}

