from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline Durbin kernel: same math as the PolyBench durbin.c reference.
# This implements the classic O(n^2) Levinson–Durbin recursion.
@proc
def kernel_durbin_base(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    z: DATA_TYPE[n] @ DRAM
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE

    # Initial conditions
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    for k in seq(1, n):
        # Update beta using the current reflection coefficient alpha
        beta = (1.0 - alpha * alpha) * beta

        # Inner dot product: sum_{i=0..k-1} r[k-i-1] * y[i]
        sum = 0.0
        for i in seq(0, k):
            sum += r[k - i - 1] * y[i]

        # New reflection coefficient alpha
        alpha = -(r[k] + sum) / beta

        # Update solution vector into a temporary buffer z
        for i in seq(0, k):
            z[i] = y[i] + alpha * y[k - i - 1]

        # Copy back into y
        for i in seq(0, k):
            y[i] = z[i]

        # Last element for this order
        y[k] = alpha


