#    parallelism and give the C backend a fixed-size inner loop to vectorize.
#    We split the loop over `i` (the dot product) into:
#       for i_sum_outer in ...
#         for i_sum_inner in 0..3:
#           ...
#    and then fully unroll `i_sum_inner`.
sum_loop = kernel_durbin.find_loop("for i in _:_")
kernel_durbin = divide_loop(
    kernel_durbin,
    sum_loop,
    div_const=4,
    new_iters=("i_sum_outer", "i_sum_inner"),
    tail="guard",
)

inner_sum = kernel_durbin.find_loop("i_sum_inner")
kernel_durbin = unroll_loop(kernel_durbin, inner_sum)

# 2. Run a simplification pass to clean up any algebra and guards introduced
#    by the tiling transformation.
kernel_durbin = simplify(kernel_durbin)
