EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *


# Baseline Levinson–Durbin kernel written in Exo.
# We implement an in-place version of the standard PolyBench durbin
# kernel that avoids the temporary z[] array by doing pairwise
# symmetric updates of y. This reduces memory traffic and improves
# cache behavior while preserving exact numerical semantics.
@proc
def kernel_durbin(
    n: size,
    r: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    alpha: DATA_TYPE
    beta: DATA_TYPE
    sum: DATA_TYPE

    # Initial conditions (match PolyBench durbin kernel).
    y[0] = -r[0]
    beta = 1.0
    alpha = -r[0]

    # Main recursion. The outer loop over k is inherently sequential.
    for k in seq(1, n):
        beta = (1.0 - alpha * alpha) * beta
        sum = 0.0

        # Accumulate: sum_{i=0}^{k-1} r[k - i - 1] * y[i]
        for i_sum in seq(0, k):
            sum += r[k - i_sum - 1] * y[i_sum]

        alpha = -(r[k] + sum) / beta

        # In-place symmetric update of y without an auxiliary buffer.
        #
        # Original code (with a temporary z[]):
        #   for i in 0..k-1:
        #       z[i] = y[i] + alpha * y[k-1-i]
        #   for i in 0..k-1:
        #       y[i] = z[i]
        #
        # This is equivalent to:
        #   y_new[i] = y_old[i] + alpha * y_old[k-1-i]
        #
        # We implement this in place by updating symmetric pairs (i, j)
        # where j = k-1-i. Each pair reads the old values exactly once
        # and writes both new values, so there is no cross-iteration
        # dependence and no need for a separate z[] array.
        for i_upd in seq(0, (k + 1) / 2):
            j: size
            a0: DATA_TYPE
            a1: DATA_TYPE

            j = k - i_upd - 1

            # Save the old values for this symmetric pair.
            a0 = y[i_upd]
            a1 = y[j]

            # Compute both updated values using the original pair.
            y[i_upd] = a0 + alpha * a1
            y[j] = a1 + alpha * a0

        # Final element of y in this iteration is alpha.
        y[k] = alpha


# ---------------------------------------------------------------------------
# Scheduling / optimization
#
# We apply simple but effective loop transformations to improve
# instruction-level parallelism and enable better vectorization:
# - Split the inner loops with a factor of 4.
# - Fully unroll the constant-size inner fragments.
# ---------------------------------------------------------------------------

kernel_durbin_opt = kernel_durbin

# 1) Split and unroll the accumulation loop over i_sum.
sum_loop = kernel_durbin_opt.find_loop("i_sum")
kernel_durbin_opt = divide_loop(
    kernel_durbin_opt,
    sum_loop,
    4,
    ("i_sum_outer", "i_sum_inner"),
    tail="guard",
)
inner_sum_loop = kernel_durbin_opt.find_loop("i_sum_inner #0")
kernel_durbin_opt = unroll_loop(kernel_durbin_opt, inner_sum_loop)

# 2) Split and unroll the in-place update loop over i_upd.
upd_loop = kernel_durbin_opt.find_loop("i_upd")
kernel_durbin_opt = divide_loop(
    kernel_durbin_opt,
    upd_loop,
    4,
    ("i_upd_outer", "i_upd_inner"),
    tail="guard",
)
inner_upd_loop = kernel_durbin_opt.find_loop("i_upd_inner #0")
kernel_durbin_opt = unroll_loop(kernel_durbin_opt, inner_upd_loop)

# 3) Simplify the resulting code to clean up expressions and remove
#    any dead conditionals introduced by the transformations.
kernel_durbin_opt = simplify(kernel_durbin_opt)

# Export the optimized kernel under the name expected by the C driver.
kernel_durbin = kernel_durbin_opt
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
